ALTER TABLE class_enrollments ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE attendance ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE subjects ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE teacher_subjects ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE teacher_classes ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE teacher_qualifications ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE teacher_documents ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE class_subjects ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE class_timetable_slots ADD COLUMN school_id INTEGER REFERENCES schools(id);
ALTER TABLE student_documents ADD COLUMN school_id INTEGER REFERENCES schools(id);
